import React, { Component } from 'react';
import classes from './Home.module.css';

class Home extends Component {

    render() {

        let message = <h2> WELCOME TO THE PLATFORM! </h2>

        return (
            <div>
                <div className={classes.Home}>
                    {message}
                </div>
            </div>
        )}
    }

export default Home;
